export function componentContract(name: string): ComponentContract | undefined { return Object.hasOwn(componentContracts, name) ? componentContracts[name as ComponentMetricName] : undefined }
export function validComponentLabels(contract: ComponentContract, labels: Record<string, unknown>): boolean {
 return Object.keys(labels).length === contract.keys.length && contract.tuples.some(tuple => contract.keys.every((key, i) => labels[key] === tuple[i]))
}
export function validComponentValue(name: string, contract: ComponentContract, value: number): boolean {
 if (!Number.isFinite(value)) return false
 if (name.endsWith('_dependency_up')) return value === -1 || value === 0 || value === 1
 return value >= 0 && (contract.unit === 'seconds' || Number.isInteger(value))
}
